PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE conversations (
  id TEXT PRIMARY KEY,
  token_hash TEXT NOT NULL,
  title TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
, user_id TEXT REFERENCES users(id));
CREATE TABLE messages (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  conversation_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,
  role TEXT NOT NULL CHECK (role IN ('user','assistant')),
  content TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE users (id TEXT PRIMARY KEY, username TEXT NOT NULL UNIQUE COLLATE NOCASE, password_hash TEXT NOT NULL, salt TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('admin','user')), disabled INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE sessions (token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at INTEGER NOT NULL);
CREATE TABLE invites (code_hash TEXT PRIMARY KEY, created_by TEXT NOT NULL REFERENCES users(id), expires_at INTEGER NOT NULL, used_by TEXT REFERENCES users(id));
CREATE TABLE memories (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, content TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE daily_usage (user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, day TEXT NOT NULL, count INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(user_id,day));
CREATE TABLE admin_audit (
 id TEXT PRIMARY KEY,
 actor_id TEXT NOT NULL,
 target_id TEXT NOT NULL,
 old_role TEXT NOT NULL CHECK(old_role IN ('admin','user')),
 new_role TEXT NOT NULL CHECK(new_role IN ('admin','user')),
 created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE voice_models (
 id TEXT PRIMARY KEY,
 user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
 name TEXT NOT NULL,
 kind TEXT NOT NULL CHECK(kind IN ('rvc','piper')),
 model_name TEXT NOT NULL,
 support_name TEXT NOT NULL,
 model_bytes INTEGER NOT NULL DEFAULT 0,
 support_bytes INTEGER NOT NULL DEFAULT 0,
 status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','ready')),
 created_at INTEGER NOT NULL
, description TEXT NOT NULL DEFAULT '', language TEXT NOT NULL DEFAULT 'pt-BR', architecture TEXT NOT NULL DEFAULT 'legacy', sample_rate INTEGER NOT NULL DEFAULT 0, model_sha256 TEXT, support_sha256 TEXT, compatibility TEXT NOT NULL DEFAULT '["windows","android","web"]', selected INTEGER NOT NULL DEFAULT 0 CHECK(selected IN (0,1)), preview_name TEXT);
CREATE TABLE voice_cloud_files (
  voice_id TEXT NOT NULL REFERENCES voice_models(id) ON DELETE CASCADE,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  part TEXT NOT NULL CHECK(part IN ('model','support','preview')),
  object_key TEXT NOT NULL UNIQUE,
  name TEXT NOT NULL,
  sha256 TEXT NOT NULL CHECK(length(sha256)=64),
  bytes INTEGER NOT NULL CHECK(bytes>=1 AND bytes<=104857600),
  content_type TEXT NOT NULL CHECK(content_type IN ('application/octet-stream','audio/wav')),
  state TEXT NOT NULL DEFAULT 'pending' CHECK(state IN ('pending','ready')),
  expires_at INTEGER NOT NULL,
  created_at INTEGER NOT NULL,
  verified_at INTEGER,
  PRIMARY KEY (voice_id,part)
);
CREATE TABLE invite_links (
 token_hash TEXT PRIMARY KEY,
 username TEXT NOT NULL COLLATE NOCASE,
 created_by TEXT NOT NULL REFERENCES users(id),
 expires_at INTEGER NOT NULL,
 used_by TEXT REFERENCES users(id),
 created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE google_drive_connections (
 user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
 refresh_token_enc TEXT NOT NULL,
 access_token_enc TEXT,
 expires_at INTEGER NOT NULL,
 folder_id TEXT
);
CREATE TABLE google_drive_oauth (
 state_hash TEXT PRIMARY KEY,
 user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
 code_verifier TEXT NOT NULL,
 expires_at INTEGER NOT NULL
);
CREATE TABLE google_drive_uploads (
 id TEXT PRIMARY KEY,
 user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
 session_url TEXT NOT NULL,
 size INTEGER NOT NULL,
 uploaded INTEGER NOT NULL DEFAULT 0,
 expires_at INTEGER NOT NULL
);
CREATE TABLE hyron_google_grounding_daily (
  day TEXT PRIMARY KEY NOT NULL,
  attempts INTEGER NOT NULL CHECK (attempts >= 0)
);
CREATE TABLE hyron_chat_drive_images (
 user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
 conversation_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,
 message_id INTEGER NOT NULL REFERENCES messages(id) ON DELETE CASCADE,
 drive_file_id TEXT NOT NULL,
 name TEXT NOT NULL,
 mime TEXT NOT NULL,
 size INTEGER NOT NULL,
 created_at TEXT NOT NULL DEFAULT (datetime('now')),
 PRIMARY KEY(user_id,message_id,drive_file_id)
);
CREATE TABLE user_timezones (user_id TEXT PRIMARY KEY NOT NULL REFERENCES users(id) ON DELETE CASCADE, time_zone TEXT NOT NULL, updated_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE hyron_humor_insults (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  user_id TEXT NOT NULL,
  insult TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE hyron_dm_threads (
 id TEXT PRIMARY KEY,
 user_a TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
 user_b TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
 created_at TEXT NOT NULL DEFAULT (datetime('now')),
 last_message_at TEXT NOT NULL DEFAULT (datetime('now')),
 CHECK(user_a <> user_b),
 CHECK(user_a < user_b),
 UNIQUE(user_a,user_b)
);
CREATE TABLE hyron_dm_messages (
 id INTEGER PRIMARY KEY AUTOINCREMENT,
 thread_id TEXT NOT NULL REFERENCES hyron_dm_threads(id) ON DELETE CASCADE,
 sender_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
 content TEXT NOT NULL CHECK(length(content) BETWEEN 1 AND 4000),
 created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
 read_at TEXT
);
CREATE TABLE hyron_dm_attachments (
 id INTEGER PRIMARY KEY AUTOINCREMENT,
 message_id INTEGER NOT NULL REFERENCES hyron_dm_messages(id) ON DELETE CASCADE,
 thread_id TEXT NOT NULL REFERENCES hyron_dm_threads(id) ON DELETE CASCADE,
 sender_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
 file_id TEXT NOT NULL,
 name TEXT NOT NULL,
 mime TEXT NOT NULL,
 size INTEGER NOT NULL CHECK(size>0 AND size<=104857600),
 created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE hyron_user_avatars (
 user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
 jpeg_base64 TEXT NOT NULL,
 updated_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE hyron_groups (
 id TEXT PRIMARY KEY,
 name TEXT NOT NULL CHECK(length(name) BETWEEN 3 AND 64),
 description TEXT NOT NULL DEFAULT '' CHECK(length(description)<=500),
 created_by TEXT NOT NULL REFERENCES users(id),
 created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
 jpeg_base64 TEXT,
 CHECK(jpeg_base64 IS NULL OR length(jpeg_base64)<=130000)
);
CREATE TABLE hyron_group_members (
 group_id TEXT NOT NULL REFERENCES hyron_groups(id) ON DELETE CASCADE,
 user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
 role TEXT NOT NULL DEFAULT 'member' CHECK(role IN ('admin','member')),
 joined_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
 PRIMARY KEY(group_id,user_id)
);
CREATE TABLE hyron_group_messages (
 id TEXT PRIMARY KEY,
 group_id TEXT NOT NULL REFERENCES hyron_groups(id) ON DELETE CASCADE,
 sender_id TEXT NOT NULL REFERENCES users(id),
 content TEXT NOT NULL CHECK(length(content) BETWEEN 1 AND 4000),
 created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
CREATE TABLE hyron_group_reads (
 group_id TEXT NOT NULL REFERENCES hyron_groups(id) ON DELETE CASCADE,
 user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
 last_read_at TEXT NOT NULL,
 PRIMARY KEY(group_id,user_id)
);
CREATE TABLE hyron_group_attachments (
 id INTEGER PRIMARY KEY AUTOINCREMENT,
 message_id TEXT NOT NULL REFERENCES hyron_group_messages(id) ON DELETE CASCADE,
 group_id TEXT NOT NULL REFERENCES hyron_groups(id) ON DELETE CASCADE,
 sender_id TEXT NOT NULL REFERENCES users(id),
 file_id TEXT NOT NULL,
 name TEXT NOT NULL,
 mime TEXT NOT NULL,
 size INTEGER NOT NULL CHECK(size>0 AND size<=104857600),
 created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
CREATE TABLE hyron_ghost_blocks (
 user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
 enabled INTEGER NOT NULL DEFAULT 0 CHECK(enabled IN (0,1)),
 reason TEXT NOT NULL DEFAULT '',
 changed_by TEXT NOT NULL REFERENCES users(id),
 changed_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
CREATE TABLE hyron_ghost_audit (
 id TEXT PRIMARY KEY,
 actor_id TEXT NOT NULL,
 target_id TEXT NOT NULL,
 enabled INTEGER NOT NULL,
 reason TEXT NOT NULL DEFAULT '',
 created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
CREATE TABLE hyron_admin_events (
 id TEXT PRIMARY KEY,
 actor_id TEXT NOT NULL REFERENCES users(id),
 action TEXT NOT NULL,
 target_type TEXT NOT NULL,
 target_id TEXT NOT NULL,
 details TEXT NOT NULL DEFAULT '{}',
 created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
CREATE TABLE hyron_interno_preferences (
  personality_id TEXT NOT NULL CHECK (personality_id IN ('basilisco','bicuco','garra-de-prata','bunga')),
  category TEXT NOT NULL,
  preference_key TEXT NOT NULL,
  preference_value TEXT NOT NULL,
  origin TEXT NOT NULL DEFAULT 'creator' CHECK (origin IN ('creator','confirmed')),
  is_locked INTEGER NOT NULL DEFAULT 0 CHECK (is_locked IN (0,1)),
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (personality_id,category,preference_key)
);
CREATE TABLE hyron_preference_candidates (
 personality_id TEXT NOT NULL CHECK(personality_id IN ('basilisco','bicuco','garra-de-prata','bunga')),
 category TEXT NOT NULL,
 preference_key TEXT NOT NULL,
 candidate_value TEXT NOT NULL,
 last_observed_day TEXT NOT NULL,
 distinct_days INTEGER NOT NULL DEFAULT 1 CHECK(distinct_days BETWEEN 1 AND 100),
 PRIMARY KEY(personality_id,category,preference_key)
);
DELETE FROM sqlite_sequence;
CREATE INDEX idx_messages_conversation ON messages(conversation_id,id);
CREATE INDEX idx_sessions_user ON sessions(user_id);
CREATE INDEX idx_memories_user ON memories(user_id);
CREATE INDEX idx_conversations_user ON conversations(user_id,created_at);
CREATE INDEX idx_admin_audit_target ON admin_audit(target_id,created_at);
CREATE INDEX idx_voice_models_user ON voice_models(user_id,created_at DESC);
CREATE UNIQUE INDEX idx_voice_models_one_selected
  ON voice_models(user_id) WHERE selected = 1;
CREATE INDEX idx_voice_cloud_owner ON voice_cloud_files(user_id,voice_id,state);
CREATE INDEX idx_invite_links_expires ON invite_links(expires_at);
CREATE INDEX idx_invite_links_username ON invite_links(username);
CREATE INDEX google_drive_upload_user ON google_drive_uploads(user_id);
CREATE INDEX idx_chat_drive_images_user ON hyron_chat_drive_images(user_id,message_id);
CREATE INDEX idx_hyron_humor_insults_recent
ON hyron_humor_insults(user_id, id DESC);
CREATE INDEX idx_hyron_dm_threads_a ON hyron_dm_threads(user_a,last_message_at);
CREATE INDEX idx_hyron_dm_threads_b ON hyron_dm_threads(user_b,last_message_at);
CREATE INDEX idx_hyron_dm_messages_thread ON hyron_dm_messages(thread_id,id DESC);
CREATE INDEX idx_hyron_dm_unread ON hyron_dm_messages(thread_id,sender_id,read_at);
CREATE INDEX idx_hyron_dm_attachments_msg ON hyron_dm_attachments(message_id);
CREATE INDEX idx_hyron_group_members_user ON hyron_group_members(user_id,group_id);
CREATE INDEX idx_hyron_group_messages_group_time ON hyron_group_messages(group_id,created_at DESC,id DESC);
CREATE INDEX idx_hyron_group_attach_message ON hyron_group_attachments(message_id);
CREATE INDEX idx_hyron_group_attach_group ON hyron_group_attachments(group_id);
CREATE INDEX idx_hyron_ghost_audit_target ON hyron_ghost_audit(target_id,created_at);
CREATE INDEX idx_hyron_admin_events_created ON hyron_admin_events(created_at DESC);
