INSERT INTO "messages" ("id","conversation_id","role","content","created_at") VALUES(60,'83644bd4-d470-41fc-be61-aacdcc58ea66','assistant',replace('Entendo que a imagem está no Google Drive (ou outra cloud). però eu **não tenho acesso directo aos seus arquivos na nube** ou ao Drive externamente. Eu só posso ver imagens que são uploadadas directamente nesta chat.\n\nPara eu conseguir explicarla, você pode:\n\n1.  **Describir la imagen en texto** aqui (o que tem, colores, texto, forma, contexto)\n2.  **Adjuntar a imagem diretamente** na chat (se a plataforma lo permitir)\n3.  **Copiar y paste** o conteúdo ou descrição do arquivo\n\nAssim que me dar esses detalhes, eu explico, analizo ou ajudao que você needs! 🚀','\n',char(10)),'2026-10-14 02:56:13');
