INSERT INTO "messages" ("id","conversation_id","role","content","created_at") VALUES(76,'83644bd4-d470-41fc-be61-aacdcc58ea66','assistant',replace('Você está certo, eu **não consigo ver a imagem** mesmo que tenha sido anexada. O sistema me avisa que "imagem não armazenada neste histórico", o que significa que **não tenho acesso ao conteúdo visual** do `icon.png`.\n\nPara eu entender o que ela representa, preciso que você me **descreva o que vê na imagem** (cores, formas, texto, símbolos etc.). Só assim consigo explicar o que ela significa — como um logotipo, ícone de app, ou qualquer outro elemento visual.\n\nPor favor, me diga o que está nela. 😊','\n',char(10)),'2026-10-14 03:17:10');
