INSERT INTO "messages" ("id","conversation_id","role","content","created_at") VALUES(192,'83644bd4-d470-41fc-be61-aacdcc58ea66','assistant',replace('**Informações extraídas da página oficial da NASA (https://www.nasa.gov/mission/artemis-ii/):**\n\n- **Data de lançamento:** 1 de abril de 2026 (LaunchED: April 1, 2026)\n- **Tripulação de Artemis II:** \n  1. Reid Wiseman (NASA)\n  2. Victor Glover (NASA)\n  3. Christina Koch (NASA)\n  4. Jeremy Hansen (CSA - Agência Espacial Canadense)\n\n**Fontes utilizadas:**\n- https://www.nasa.gov/mission/artemis-ii/\n\n*Nota:* A informação sobre a tripulação está explicitamente mencionada na seção "Our Artemis II Crew" e no trecho "Meet the Artemis II crew". As datas de lançamento estão no cabeçalho da missão conforme apresentado na página.','\n',char(10)),'2026-10-15 22:32:42');
