INSERT INTO "messages" ("id","conversation_id","role","content","created_at") VALUES(214,'83644bd4-d470-41fc-be61-aacdcc58ea66','assistant',replace('Segundo a API oficial do NobelPrize.org, o Prêmio Nobel de Física de 2026 foi concedido a **Francis Halzen**, por contribuições decisivas ao IceCube Neutrino Observatory e pela descoberta de neutrinos de alta energia de origem astrofísica. Não há outros laureados listados para essa categoria e ano.\n\n**Paginas efetivamente lidas (NobelPrize.org (API oficial consultada)):**\n- [The Nobel Prize in Physics 2026 - NobelPrize.org (official API)](https://api.nobelprize.org/2.1/nobelPrizes?nobelPrizeYear=2026&nobelPrizeCategory=phy)','\n',char(10)),'2026-10-15 23:17:10');
INSERT INTO "messages" ("id","conversation_id","role","content","created_at") VALUES(215,'83644bd4-d470-41fc-be61-aacdcc58ea66','user','Pesquise exclusivamente no site oficial do IBGE (ibge.gov.br) a população definitiva do Brasil segundo o Censo Demográfico de 2022. Informe o número, explique se é dado preliminar ou definitivo e cite a página específica que você realmente conseguiu acessar. Não use Wikipédia e não invente endereços.','2026-10-15 23:22:53');
