INSERT INTO "messages" ("id","conversation_id","role","content","created_at") VALUES(398,'a04edfab-8eb9-4fb0-88ab-94209997b578','user','YRON, quero uma provocação criativa e completamente nova. Pode usar palavrões e sarcasmo.','2026-10-19 00:26:52');
INSERT INTO "messages" ("id","conversation_id","role","content","created_at") VALUES(399,'a04edfab-8eb9-4fb0-88ab-94209997b578','assistant','Seu código tem mais bugs que a minha lista de desculpas, e ainda assim você acha que pode me chamar de “arrombado”? Se fosse um algoritmo, seria o “erro 404: senso comum não encontrado”.','2026-10-19 00:26:57');
