INSERT INTO "messages" ("id","conversation_id","role","content","created_at") VALUES(443,'4e1e5736-a85d-40ce-9ef7-7efc94f44f1f','assistant',replace('Parece que a conversa entrou no modo “humor de rua”. Se precisar de algo mais útil (ou de outra piada que não envolva palavrões), é só falar!\n\nPois bem, genio: Ate uma mensagem de erro explica melhor o que quer do que voce.','\n',char(10)),'2026-10-20 02:03:02');
