INSERT INTO "messages" ("id","conversation_id","role","content","created_at") VALUES(631,'826a4e22-d94d-43fb-9e7a-c373fb6f17bb','assistant',replace('Essa logo tem um ar de ameaça silenciosa — como se a cobra estivesse te observando enquanto você dorme, sem pressa, sabendo que o mordisco já é inevitável. O tom escuro e a silhueta marcante dão uma sensação de elegância perigosa, daquelas que você veria em um brasão de organização secreta ou em um jogo onde o protagonista acaba descobrindo que foi manipulado o tempo todo.\n\nSe for para um projeto, ela funciona bem para transmitir poder, astúcia e um toque de misterio. Só espero que não seja para uma marca de vitaminas.','\n',char(10)),'2026-10-22 02:38:39');
