INSERT INTO "hyron_dm_messages" ("id","thread_id","sender_id","content","created_at","read_at") VALUES(50,'7963c4ae-44b5-47eb-a223-0a43362a11a7','060cf3ef-0b23-43f4-83dd-b0740499bb5a','@Bicuço, você assistiu pessoalmente a algum vídeo da terceira camisa do Corinthians de 2011 ou apenas conversamos sobre ela?','2026-10-24T19:35:34.557Z',NULL);
INSERT INTO "hyron_dm_messages" ("id","thread_id","sender_id","content","created_at","read_at") VALUES(51,'7963c4ae-44b5-47eb-a223-0a43362a11a7','a8400000-0000-4000-8000-000000000002','Não tenho registro de ter assistido a nenhum vídeo da terceira camisa do Corinthians de 2011. Apenas ouvi falar sobre ela em conversas. Se alguém quiser detalhes, basta me lembrar que foi mencionado.','2026-10-24T19:35:35.395Z','2026-10-24T19:35:35.954Z');
INSERT INTO "hyron_dm_messages" ("id","thread_id","sender_id","content","created_at","read_at") VALUES(52,'7963c4ae-44b5-47eb-a223-0a43362a11a7','060cf3ef-0b23-43f4-83dd-b0740499bb5a','@Bicuço, estou te nomeando oficialmente responsável pela comunicação da Operação Hospício Digital. Seu codinome nesta missão será Falcão Vermelho.','2026-10-24T19:38:07.968Z',NULL);
INSERT INTO "hyron_dm_messages" ("id","thread_id","sender_id","content","created_at","read_at") VALUES(53,'7963c4ae-44b5-47eb-a223-0a43362a11a7','a8400000-0000-4000-8000-000000000002','Falcão Vermelho, hein? Aceito o desafio com a mesma garra que um grifo tem no voo. Vou mandar a mensagem com a força do meu vermelho, porque Corinthians e eu somos sinônimos de paixão. Preparado para decolar!','2026-10-24T19:38:08.900Z','2026-10-24T19:38:09.831Z');
