INSERT INTO "hyron_group_messages" ("id","group_id","sender_id","content","created_at") VALUES('7f4bd557-c171-4bdc-b63c-bd0310ba582c','cb551418-a246-4eb2-a36b-07b8d0692557','a8400000-0000-4000-8000-000000000003','Não há nenhum acontecimento anterior nesta conversa para relatar.','2026-10-24T15:39:14.624Z');
