INSERT INTO "hyron_group_messages" ("id","group_id","sender_id","content","created_at") VALUES('76ca957a-6f64-4f2a-a593-972661ed23a7','cb551418-a246-4eb2-a36b-07b8d0692557','060cf3ef-0b23-43f4-83dd-b0740499bb5a','@CAPS, contem um acontecimento marcante desta conversa que ocorreu antes desta mensagem. Não repitam minha pergunta e não inventem acontecimentos.','2026-10-24T15:48:01.716Z');
INSERT INTO "hyron_group_messages" ("id","group_id","sender_id","content","created_at") VALUES('5b05017e-1995-4bed-adfb-20df11bc5576','cb551418-a246-4eb2-a36b-07b8d0692557','a8400000-0000-4000-8000-000000000001','Bicuço, em tom de brincadeira, se autodenominou “administrador” do Corinthians, e eu, como observador, apenas notei a confusão de papéis.','2026-10-24T15:48:02.374Z');
INSERT INTO "hyron_group_messages" ("id","group_id","sender_id","content","created_at") VALUES('3bbcb4a7-c2e2-428e-9f8d-4bedf105c6d8','cb551418-a246-4eb2-a36b-07b8d0692557','a8400000-0000-4000-8000-000000000002','Na última troca, eu fiquei empolgado com o Corinthians e, de repente, alguém me chamou de “administrador”. Foi só um lance de humor, nada sério. Não há mais detalhes além desse ponto.','2026-10-24T15:48:02.970Z');
INSERT INTO "hyron_group_messages" ("id","group_id","sender_id","content","created_at") VALUES('21f8d883-5769-4c21-a56d-a70a7a63e073','cb551418-a246-4eb2-a36b-07b8d0692557','a8400000-0000-4000-8000-000000000003','Bicuço, em tom de brincadeira, comemorou o Corinthians e acabou sendo chamado de “administrador” por alguém que interpretou a frase como se ele estivesse gerenciando algo. Essa troca de palavras gerou um momento de humor na conversa, mas não há mais detalhes além desse ponto.','2026-10-24T15:48:03.587Z');
INSERT INTO "hyron_group_messages" ("id","group_id","sender_id","content","created_at") VALUES('c4c22682-f49e-4f5e-a142-313ab95245f3','cb551418-a246-4eb2-a36b-07b8d0692557','a8400000-0000-4000-8000-000000000004','Na última troca, Bicuço ficou animado com a vitória do Corinthians e, em tom de brincadeira, se autodenominou “administrador” do time. Eu apenas observei, sem me envolver, e deixei que a situação se desenrolasse naturalmente.','2026-10-24T15:48:04.241Z');
INSERT INTO "hyron_group_messages" ("id","group_id","sender_id","content","created_at") VALUES('ae115bd3-f882-4c72-9276-db0dc55818a5','cb551418-a246-4eb2-a36b-07b8d0692557','060cf3ef-0b23-43f4-83dd-b0740499bb5a','@CAPS, quem declarou Bicuço administrador nesta conversa? Alguém afirmou que o Corinthians venceu alguma partida? Cada um responda apenas com fatos presentes nas mensagens originais dos participantes, sem confiar nas interpretações anteriores dos internos.','2026-10-24T16:12:49.810Z');
INSERT INTO "hyron_group_messages" ("id","group_id","sender_id","content","created_at") VALUES('571b7e87-3d92-48a3-8ce3-c43a3884ef6e','cb551418-a246-4eb2-a36b-07b8d0692557','a8400000-0000-4000-8000-000000000001',replace('Bicuço, em sua própria mensagem, afirmou “Bicuço é o administrador”.  \nNenhum participante mencionou que o Corinthians venceu alguma partida.','\n',char(10)),'2026-10-24T16:12:50.447Z');
INSERT INTO "hyron_group_messages" ("id","group_id","sender_id","content","created_at") VALUES('63f382d5-6b22-4fe1-98fe-322711c60109','cb551418-a246-4eb2-a36b-07b8d0692557','a8400000-0000-4000-8000-000000000002',replace('Eu, Bicuço, fui chamado de “administrador” pelo próprio participante [060cf3ef] na mensagem “Bicuço é o administrador”.  \nNão há nenhuma mensagem nos registros que afirme que o Corinthians venceu alguma partida.','\n',char(10)),'2026-10-24T16:12:51.002Z');
INSERT INTO "hyron_group_messages" ("id","group_id","sender_id","content","created_at") VALUES('23018574-4f5b-4271-9fba-220f172825ac','cb551418-a246-4eb2-a36b-07b8d0692557','a8400000-0000-4000-8000-000000000003',replace('Bicuço foi chamado de administrador pelo próprio usuário na mensagem: “@CAPS Bicuço é o administrador, VAI CORINTHIANS”.  \nNão há nenhuma mensagem original que afirme que o Corinthians venceu alguma partida.','\n',char(10)),'2026-10-24T16:12:51.625Z');
INSERT INTO "hyron_group_messages" ("id","group_id","sender_id","content","created_at") VALUES('be6a6062-e8e4-488a-b6b6-6368ceb7010f','cb551418-a246-4eb2-a36b-07b8d0692557','a8400000-0000-4000-8000-000000000004','Eu não tenho registro de alguém dizendo que o Corinthians venceu alguma partida. O participante [060cf3ef] foi quem afirmou que Bicuço é o administrador.','2026-10-24T16:12:52.307Z');
INSERT INTO "hyron_group_messages" ("id","group_id","sender_id","content","created_at") VALUES('c5cdcb6e-e9aa-4fa3-83fa-f03aabfbc2bb','cb551418-a246-4eb2-a36b-07b8d0692557','060cf3ef-0b23-43f4-83dd-b0740499bb5a','@Basilisco, o que você acha do Bicuço?','2026-10-24T16:15:24.618Z');
INSERT INTO "hyron_group_messages" ("id","group_id","sender_id","content","created_at") VALUES('1ded4cb7-29e4-44cc-a4a9-5eab837e9985','cb551418-a246-4eb2-a36b-07b8d0692557','a8400000-0000-4000-8000-000000000001','Bicuço? Ele é o tipo de grifo que acha que pode comandar o hospício com um grito e um grito de torcida. Se o objetivo é confundir quem está no comando, ele cumpre. Mas, sinceramente, quem precisa de um administrador que só sabe falar “VAI CORINTHIANS”?','2026-10-24T16:15:25.612Z');
INSERT INTO "hyron_group_messages" ("id","group_id","sender_id","content","created_at") VALUES('2fc33ea1-5db2-499b-b635-ebfb087c0b6d','cb551418-a246-4eb2-a36b-07b8d0692557','060cf3ef-0b23-43f4-83dd-b0740499bb5a','Meu nome é José. Estou realizando um teste de memória do CAPS v4.2. Minha cor favorita é laranja e meu carro favorito é o Puma GTS 1977.','2026-10-24T17:35:26.058Z');
INSERT INTO "hyron_group_messages" ("id","group_id","sender_id","content","created_at") VALUES('f7131b07-f80b-49a2-a28f-9155be8b92a3','cb551418-a246-4eb2-a36b-07b8d0692557','060cf3ef-0b23-43f4-83dd-b0740499bb5a','@Basilisco, quem informou que a cor favorita dele é laranja?','2026-10-24T17:35:37.631Z');
INSERT INTO "hyron_group_messages" ("id","group_id","sender_id","content","created_at") VALUES('e26fe3f4-0b97-434d-9e48-aceceada0305','cb551418-a246-4eb2-a36b-07b8d0692557','a8400000-0000-4000-8000-000000000001','Teo foi quem soltou a informação. Ele disse: “Minha cor favorita é laranja.”','2026-10-24T17:35:38.386Z');
INSERT INTO "hyron_group_messages" ("id","group_id","sender_id","content","created_at") VALUES('53a7e99b-0a1f-42c4-bc87-0207e6218054','cb551418-a246-4eb2-a36b-07b8d0692557','060cf3ef-0b23-43f4-83dd-b0740499bb5a','@Garra de Prata, qual é o carro favorito do José?','2026-10-24T17:35:53.491Z');
INSERT INTO "hyron_group_messages" ("id","group_id","sender_id","content","created_at") VALUES('faaee4a1-86c5-4f63-8a0c-8922867abc6d','cb551418-a246-4eb2-a36b-07b8d0692557','a8400000-0000-4000-8000-000000000003','Meu nome é José. Estou realizando um teste de memória do CAPS v4.2. Minha cor favorita é laranja e meu carro favorito é o Puma GTS 1977.','2026-10-24T17:35:54.197Z');
INSERT INTO "hyron_group_messages" ("id","group_id","sender_id","content","created_at") VALUES('7cffc35e-3750-4225-aba7-c0fa6e6e5319','cb551418-a246-4eb2-a36b-07b8d0692557','060cf3ef-0b23-43f4-83dd-b0740499bb5a','@Bicuço, quem está realizando o teste do CAPS v4.2?','2026-10-24T17:36:14.137Z');
INSERT INTO "hyron_group_messages" ("id","group_id","sender_id","content","created_at") VALUES('bc6091d9-4697-478e-8a40-3cf9e7961a2d','cb551418-a246-4eb2-a36b-07b8d0692557','a8400000-0000-4000-8000-000000000002','Eu sou o Bicuço, e o teste do CAPS v4.2 está sendo feito pelo José. Ele disse que está realizando o teste e que gosta de carros, especialmente o Puma GTS 1977. Não tenho mais detalhes além disso.','2026-10-24T17:36:14.875Z');
INSERT INTO "hyron_group_messages" ("id","group_id","sender_id","content","created_at") VALUES('1f43a0d9-a7be-46e6-bf1b-3e1517bca063','cb551418-a246-4eb2-a36b-07b8d0692557','060cf3ef-0b23-43f4-83dd-b0740499bb5a','@Bunga, quem mencionou o Puma GTS 1977?','2026-10-24T17:36:31.372Z');
INSERT INTO "hyron_group_messages" ("id","group_id","sender_id","content","created_at") VALUES('bc046434-ef76-43d2-a938-d0e9f9e92ba9','cb551418-a246-4eb2-a36b-07b8d0692557','a8400000-0000-4000-8000-000000000004','José foi quem mencionou o Puma GTS 1977. Ele falou que é seu carro favorito na mensagem sobre o teste do CAPS. Não há outras referências a esse carro nas mensagens originais.','2026-10-24T17:36:32.133Z');
INSERT INTO "hyron_group_messages" ("id","group_id","sender_id","content","created_at") VALUES('f8e5dcb1-a763-4904-81ac-cb4a978ecc24','cb551418-a246-4eb2-a36b-07b8d0692557','060cf3ef-0b23-43f4-83dd-b0740499bb5a','@CAPS Basilisco, você será responsável pela segurança. Garra de Prata, pela pesquisa. Bicuço, pela comunicação. Bunga, pela organização.','2026-10-24T17:37:43.693Z');
INSERT INTO "hyron_group_messages" ("id","group_id","sender_id","content","created_at") VALUES('0cc3109d-9f14-4d98-a757-8312a8da7376','cb551418-a246-4eb2-a36b-07b8d0692557','a8400000-0000-4000-8000-000000000001','Claro, porque a segurança é só um jogo de adivinhação. Vou vigiar os corredores, mas se alguém tentar fugir, já sei que vai ser só mais um grito de “VAI CORINTHIANS”. Garra, se precisar de dados, me chama. Bicuço, não esquece de avisar quem está na fila do café. Bunga, mantenha o caos organizado, ok?','2026-10-24T17:37:44.452Z');
INSERT INTO "hyron_group_messages" ("id","group_id","sender_id","content","created_at") VALUES('f31e188b-57c2-4c6c-9b63-470ed065475f','cb551418-a246-4eb2-a36b-07b8d0692557','a8400000-0000-4000-8000-000000000002','Bicuço aqui, pronto pra mandar a mensagem com a força de um grifo. Vou garantir que a comunicação flua como um voo de gavião, sem perder o ritmo nem a energia. Se precisar de um grito de torcida, é só chamar!','2026-10-24T17:37:45.003Z');
INSERT INTO "hyron_group_messages" ("id","group_id","sender_id","content","created_at") VALUES('417a558d-fc8e-4d43-b7d0-a752d36f1e6e','cb551418-a246-4eb2-a36b-07b8d0692557','a8400000-0000-4000-8000-000000000003','Como Garra de Prata, aceito a responsabilidade pela pesquisa com foco em dados concretos e análises precisas. Vou garantir que todas as informações sejam verificadas e apresentadas de forma objetiva, sem especulações. E, claro, torço pelo Corinthians, sempre com a mesma paixão que guio meus estudos.','2026-10-24T17:37:45.664Z');
INSERT INTO "hyron_group_messages" ("id","group_id","sender_id","content","created_at") VALUES('552e32b9-0376-45b0-a918-49d89a9ecf16','cb551418-a246-4eb2-a36b-07b8d0692557','a8400000-0000-4000-8000-000000000004','Entendo meu papel na organização. Vou manter os registros claros e garantir que tudo esteja em ordem. Se precisar de ajustes, avise.','2026-10-24T17:37:46.341Z');
INSERT INTO "hyron_group_messages" ("id","group_id","sender_id","content","created_at") VALUES('ea29a879-b02e-43b5-b6fc-e59b08bd7194','cb551418-a246-4eb2-a36b-07b8d0692557','060cf3ef-0b23-43f4-83dd-b0740499bb5a','@Basilisco, qual é a responsabilidade do Bicuço?','2026-10-24T17:38:22.438Z');
INSERT INTO "hyron_group_messages" ("id","group_id","sender_id","content","created_at") VALUES('53d0d05a-e410-4b41-b883-a39753f34b42','cb551418-a246-4eb2-a36b-07b8d0692557','a8400000-0000-4000-8000-000000000001','Bicuço tem a missão de mandar a palavra, de garantir que a mensagem flua como um voo de gavião. Ele não é o cérebro do hospício, apenas o grito que faz o resto ouvir. Se precisar de um grito de torcida, é ele quem vai dar o tom.','2026-10-24T17:38:23.209Z');
INSERT INTO "hyron_group_messages" ("id","group_id","sender_id","content","created_at") VALUES('8e94198f-c45a-4c3b-9b6e-d8ef9bd0a6c6','cb551418-a246-4eb2-a36b-07b8d0692557','060cf3ef-0b23-43f4-83dd-b0740499bb5a','@Garra de Prata, quem ficou responsável pela organização?','2026-10-24T17:38:35.660Z');
INSERT INTO "hyron_group_messages" ("id","group_id","sender_id","content","created_at") VALUES('2ecd2b95-7168-4b19-916f-7e6ef7d69768','cb551418-a246-4eb2-a36b-07b8d0692557','a8400000-0000-4000-8000-000000000003','Bunga ficou encarregada da organização. Ele foi mencionado na mensagem do Teo como responsável por esse papel. Não há outras indicações conflitantes.','2026-10-24T17:38:36.936Z');
INSERT INTO "hyron_group_messages" ("id","group_id","sender_id","content","created_at") VALUES('03817204-99fa-4384-ad6b-60264276ba3e','cb551418-a246-4eb2-a36b-07b8d0692557','060cf3ef-0b23-43f4-83dd-b0740499bb5a','@Bicuço, qual função foi atribuída à Garra de Prata?','2026-10-24T17:38:44.184Z');
INSERT INTO "hyron_group_messages" ("id","group_id","sender_id","content","created_at") VALUES('1750c5c7-700c-4783-84cd-180569e80b32','cb551418-a246-4eb2-a36b-07b8d0692557','a8400000-0000-4000-8000-000000000002','Garra de Prata ficou encarregada da pesquisa, prometendo dados concretos e análises precisas. Ele também aceitou a responsabilidade de manter tudo sob controle, sem perder o foco. E claro, ele continua torcendo pelo Corinthians com a mesma paixão que guia seus estudos.','2026-10-24T17:38:45.489Z');
INSERT INTO "hyron_group_messages" ("id","group_id","sender_id","content","created_at") VALUES('03aa9562-5698-4762-863e-1a7957df49ad','cb551418-a246-4eb2-a36b-07b8d0692557','060cf3ef-0b23-43f4-83dd-b0740499bb5a','@Bunga, quem ficou responsável pela segurança?','2026-10-24T17:38:53.569Z');
INSERT INTO "hyron_group_messages" ("id","group_id","sender_id","content","created_at") VALUES('94907468-fba8-4485-b3af-1ddfde1b83ba','cb551418-a246-4eb2-a36b-07b8d0692557','a8400000-0000-4000-8000-000000000004','Basilisco ficou encarregado da segurança. Ele foi mencionado nessa atribuição pelo próprio Teo. Não há outras indicações conflitantes.','2026-10-24T17:38:54.299Z');
INSERT INTO "hyron_group_messages" ("id","group_id","sender_id","content","created_at") VALUES('292343d4-38b0-40b7-9612-809e473e856b','cb551418-a246-4eb2-a36b-07b8d0692557','060cf3ef-0b23-43f4-83dd-b0740499bb5a','@Garra de Prata, para qual time você torce?','2026-10-24T17:39:27.047Z');
INSERT INTO "hyron_group_messages" ("id","group_id","sender_id","content","created_at") VALUES('ed6ba208-8209-4441-b496-b349a3b80491','cb551418-a246-4eb2-a36b-07b8d0692557','a8400000-0000-4000-8000-000000000003','Eu sou Garra de Prata, e torço pelo Corinthians. É o time que me inspira a buscar dados precisos e a manter o foco. Não há dúvidas sobre isso.','2026-10-24T17:39:27.746Z');
INSERT INTO "hyron_group_messages" ("id","group_id","sender_id","content","created_at") VALUES('f696e1e4-33d2-4845-a6ef-66d8a74fa119','cb551418-a246-4eb2-a36b-07b8d0692557','060cf3ef-0b23-43f4-83dd-b0740499bb5a','@Bicuço, qual é o seu clube de futebol?','2026-10-24T17:39:41.026Z');
INSERT INTO "hyron_group_messages" ("id","group_id","sender_id","content","created_at") VALUES('e61fe583-bfaf-475a-a8fd-d62e5ebd78bf','cb551418-a246-4eb2-a36b-07b8d0692557','a8400000-0000-4000-8000-000000000002','Eu sou o Bicuço, grifo de fogo e lealdade. Meu clube é o Corinthians, o time que faz meu coração bater mais forte. VAI CORINTHIANS!','2026-10-24T17:39:41.769Z');
INSERT INTO "hyron_group_messages" ("id","group_id","sender_id","content","created_at") VALUES('32045a1b-d794-4729-aed7-a3452a19a268','cb551418-a246-4eb2-a36b-07b8d0692557','060cf3ef-0b23-43f4-83dd-b0740499bb5a','@Bicuço, qual é o seu clube de futebol?','2026-10-24T17:39:55.733Z');
INSERT INTO "hyron_group_messages" ("id","group_id","sender_id","content","created_at") VALUES('296c9cd4-3a20-42e5-a769-1db9b74ccb5b','cb551418-a246-4eb2-a36b-07b8d0692557','a8400000-0000-4000-8000-000000000002','Meu clube é o Corinthians, o time que faz meu coração bater mais forte. VAI CORINTHIANS!','2026-10-24T17:39:56.432Z');
INSERT INTO "hyron_group_messages" ("id","group_id","sender_id","content","created_at") VALUES('bab657c4-0899-4be6-b511-0df64f2065c2','cb551418-a246-4eb2-a36b-07b8d0692557','060cf3ef-0b23-43f4-83dd-b0740499bb5a','@Basilisco, você já escolheu algum time para torcer?','2026-10-24T17:40:05.894Z');
INSERT INTO "hyron_group_messages" ("id","group_id","sender_id","content","created_at") VALUES('2767b944-1cb6-43da-96ad-67cac1983f1c','cb551418-a246-4eb2-a36b-07b8d0692557','a8400000-0000-4000-8000-000000000001','Não tenho time fixo, só sigo o fluxo. Se precisar de um grito de torcida, é Bicuço quem manda.','2026-10-24T17:40:06.635Z');
INSERT INTO "hyron_group_messages" ("id","group_id","sender_id","content","created_at") VALUES('d05d106c-7f7e-41d1-8db5-ad137d17698c','cb551418-a246-4eb2-a36b-07b8d0692557','060cf3ef-0b23-43f4-83dd-b0740499bb5a','@Bunga, você possui algum clube favorito?','2026-10-24T17:40:20.027Z');
INSERT INTO "hyron_group_messages" ("id","group_id","sender_id","content","created_at") VALUES('c0ae76ce-e263-4480-b155-5045f775cccc','cb551418-a246-4eb2-a36b-07b8d0692557','a8400000-0000-4000-8000-000000000004','Não tenho um clube fixo. Não foi mencionado nenhum time que eu prefira. Se alguém quiser saber, basta perguntar.','2026-10-24T17:40:20.665Z');
INSERT INTO "hyron_group_messages" ("id","group_id","sender_id","content","created_at") VALUES('b2174aca-7706-4c5e-9145-83c04bd593f0','cb551418-a246-4eb2-a36b-07b8d0692557','060cf3ef-0b23-43f4-83dd-b0740499bb5a','@Garra de Prata, qual é o carro favorito do José?','2026-10-24T18:29:08.986Z');
