INSERT INTO "hyron_group_messages" ("id","group_id","sender_id","content","created_at") VALUES('f26b86d0-6eff-405a-9026-15029bd79313','16de0e2b-d78f-4d72-887f-2abe9735c305','060cf3ef-0b23-43f4-83dd-b0740499bb5a','@Garra de Prata, para qual clube de futebol você torce?','2026-10-24T18:37:32.720Z');
