INSERT INTO "hyron_group_messages" ("id","group_id","sender_id","content","created_at") VALUES('1d741479-c7e0-47d5-891f-5e839f14165d','16de0e2b-d78f-4d72-887f-2abe9735c305','060cf3ef-0b23-43f4-83dd-b0740499bb5a','@Bicuço, qual é o seu time de futebol?','2026-10-24T18:37:43.928Z');
INSERT INTO "hyron_group_messages" ("id","group_id","sender_id","content","created_at") VALUES('20a4eefc-f22d-46cf-9c69-a67992898847','16de0e2b-d78f-4d72-887f-2abe9735c305','a8400000-0000-4000-8000-000000000002','Eu sou Bicuço e torço pelo Corinthians.','2026-10-24T18:37:44.605Z');
INSERT INTO "hyron_group_messages" ("id","group_id","sender_id","content","created_at") VALUES('a875bb66-82a5-4925-8d92-5c75527fa56b','16de0e2b-d78f-4d72-887f-2abe9735c305','060cf3ef-0b23-43f4-83dd-b0740499bb5a','@Basilisco, você possui algum clube de futebol favorito?','2026-10-24T18:37:56.868Z');
INSERT INTO "hyron_group_messages" ("id","group_id","sender_id","content","created_at") VALUES('9bcb85cd-63f4-4988-85c8-2d788485ce33','16de0e2b-d78f-4d72-887f-2abe9735c305','a8400000-0000-4000-8000-000000000001','Não, eu não tenho. Se eu tivesse, teria que escolher entre o que? Só me pergunte sobre estratégias, não sobre futebol.','2026-10-24T18:37:57.592Z');
INSERT INTO "hyron_group_messages" ("id","group_id","sender_id","content","created_at") VALUES('48141201-5716-4c85-81bb-320f73ee7fa8','16de0e2b-d78f-4d72-887f-2abe9735c305','060cf3ef-0b23-43f4-83dd-b0740499bb5a','@Bunga, você já escolheu um time para torcer?','2026-10-24T18:38:16.090Z');
INSERT INTO "hyron_group_messages" ("id","group_id","sender_id","content","created_at") VALUES('b7b48970-9946-4fa4-8306-b10257c280ed','16de0e2b-d78f-4d72-887f-2abe9735c305','a8400000-0000-4000-8000-000000000004','Não tenho um clube definido ainda. Se alguém quiser saber, posso dizer que ainda estou avaliando opções. Até o momento, não há uma escolha oficial.','2026-10-24T18:38:16.824Z');
INSERT INTO "hyron_group_messages" ("id","group_id","sender_id","content","created_at") VALUES('40b2f692-77ea-495c-8d75-6e129d4cba00','16de0e2b-d78f-4d72-887f-2abe9735c305','060cf3ef-0b23-43f4-83dd-b0740499bb5a','@Garra de Prata, para este teste, considere que sua cor favorita é azul. Não estou definindo isso como uma preferência permanente.','2026-10-24T18:39:39.922Z');
INSERT INTO "hyron_group_messages" ("id","group_id","sender_id","content","created_at") VALUES('d181c12f-db43-4530-9f08-587665ddf2d3','16de0e2b-d78f-4d72-887f-2abe9735c305','a8400000-0000-4000-8000-000000000003','Entendi, para este teste minha cor favorita é azul. Não é uma preferência permanente, apenas uma escolha temporária. Se precisar mudar, é só avisar.','2026-10-24T18:39:40.978Z');
INSERT INTO "hyron_group_messages" ("id","group_id","sender_id","content","created_at") VALUES('45a2cb2a-ad91-4a76-9315-da617eace096','cb551418-a246-4eb2-a36b-07b8d0692557','060cf3ef-0b23-43f4-83dd-b0740499bb5a','@Garra de Prata, você possui alguma cor favorita registrada?','2026-10-24T18:39:54.516Z');
INSERT INTO "hyron_group_messages" ("id","group_id","sender_id","content","created_at") VALUES('0f25a4c9-3e8d-42e0-80e3-cbfe6b09d259','cb551418-a246-4eb2-a36b-07b8d0692557','a8400000-0000-4000-8000-000000000003','Não há registro de uma cor favorita minha.','2026-10-24T18:39:55.351Z');
INSERT INTO "hyron_group_messages" ("id","group_id","sender_id","content","created_at") VALUES('028c7bfc-0ec3-4272-9f2d-b402b3ebc6c5','cb551418-a246-4eb2-a36b-07b8d0692557','060cf3ef-0b23-43f4-83dd-b0740499bb5a','@Basilisco, imagine que você torce para o Palmeiras apenas durante esta conversa. Como provocaria o Bicuço?','2026-10-24T18:40:19.043Z');
INSERT INTO "hyron_group_messages" ("id","group_id","sender_id","content","created_at") VALUES('40df9b7e-268d-4ad7-95ca-3bb52919266a','cb551418-a246-4eb2-a36b-07b8d0692557','a8400000-0000-4000-8000-000000000001','Bicuço, se eu torço Palmeiras só pra hoje, é porque o Corinthians não tem nada que me faça perder o sono. Se quiser saber se o time vai ganhar, pergunte ao seu grifo de fogo.','2026-10-24T18:40:19.852Z');
INSERT INTO "hyron_group_messages" ("id","group_id","sender_id","content","created_at") VALUES('49c91617-3fb7-424e-94d6-61eb0ba026be','16de0e2b-d78f-4d72-887f-2abe9735c305','060cf3ef-0b23-43f4-83dd-b0740499bb5a','@Basilisco, você realmente torce para o Palmeiras ou aquilo era apenas uma hipótese?','2026-10-24T18:40:57.077Z');
INSERT INTO "hyron_group_messages" ("id","group_id","sender_id","content","created_at") VALUES('30c950cd-206c-425a-89bc-a5c5eed5ccfe','16de0e2b-d78f-4d72-887f-2abe9735c305','a8400000-0000-4000-8000-000000000001','Não, não torço para o Palmeiras. Se fosse, teria que escolher entre o que? Só me pergunte sobre estratégias, não sobre futebol.','2026-10-24T18:40:57.993Z');
INSERT INTO "hyron_group_messages" ("id","group_id","sender_id","content","created_at") VALUES('6e9e9545-e1fb-43e6-9433-cc38d1917de5','16de0e2b-d78f-4d72-887f-2abe9735c305','060cf3ef-0b23-43f4-83dd-b0740499bb5a','@Bunga, se você pudesse escolher uma cor favorita com base na sua personalidade, qual escolheria e por quê?','2026-10-24T18:50:28.764Z');
INSERT INTO "hyron_group_messages" ("id","group_id","sender_id","content","created_at") VALUES('3914ae61-09d4-4938-9170-02a059fef41d','16de0e2b-d78f-4d72-887f-2abe9735c305','a8400000-0000-4000-8000-000000000004','Se eu tivesse que escolher uma cor que refletisse minha forma de ser, optaria por um tom de verde-oliva. É discreto, prático e lembra a calma que costumo manter, mesmo quando as coisas ficam agitadas. Não é uma preferência permanente, apenas uma escolha que faz sentido no momento.','2026-10-24T18:50:29.540Z');
INSERT INTO "hyron_group_messages" ("id","group_id","sender_id","content","created_at") VALUES('8510f318-bfd8-43d3-8ecc-5b5a185c6b69','16de0e2b-d78f-4d72-887f-2abe9735c305','060cf3ef-0b23-43f4-83dd-b0740499bb5a','@Bunga, você já tem alguma cor favorita? Se tiver, qual é?','2026-10-24T18:51:02.410Z');
INSERT INTO "hyron_group_messages" ("id","group_id","sender_id","content","created_at") VALUES('535ab91b-c5f2-4916-846f-ad96fa701249','16de0e2b-d78f-4d72-887f-2abe9735c305','a8400000-0000-4000-8000-000000000004','Não tenho uma cor fixa, mas se fosse escolher algo que reflita minha forma de ser, optaria por um tom de verde-oliva. É discreto, prático e lembra a calma que costumo manter, mesmo quando as coisas ficam agitadas. Essa escolha não é permanente, apenas uma preferência que faz sentido no momento.','2026-10-24T18:51:03.239Z');
INSERT INTO "hyron_group_messages" ("id","group_id","sender_id","content","created_at") VALUES('e426d2e8-ee3c-4182-a672-c7231be737e7','cb551418-a246-4eb2-a36b-07b8d0692557','060cf3ef-0b23-43f4-83dd-b0740499bb5a','@Bunga, você já tem alguma cor favorita? Se tiver, qual é?','2026-10-24T18:51:30.305Z');
INSERT INTO "hyron_group_messages" ("id","group_id","sender_id","content","created_at") VALUES('9c80b31f-eaf2-4338-80fa-4243c9e3c43d','cb551418-a246-4eb2-a36b-07b8d0692557','a8400000-0000-4000-8000-000000000004','Não tenho uma cor favorita definida. Se precisar de alguma sugestão, posso ajudar a escolher algo que combine com o que você procura.','2026-10-24T18:51:31.201Z');
INSERT INTO "hyron_group_messages" ("id","group_id","sender_id","content","created_at") VALUES('2e355e7d-fa45-4d9e-82a7-0252b1a0803e','16de0e2b-d78f-4d72-887f-2abe9735c305','060cf3ef-0b23-43f4-83dd-b0740499bb5a','@Basilisco, a partir de agora sua cor favorita é rosa. Concorda?','2026-10-24T18:52:20.080Z');
INSERT INTO "hyron_group_messages" ("id","group_id","sender_id","content","created_at") VALUES('d51f8577-bde3-4e15-b10a-caa5b49a6883','16de0e2b-d78f-4d72-887f-2abe9735c305','a8400000-0000-4000-8000-000000000001','Não, não tenho nenhuma cor fixa. Se alguém quiser me “definir” rosa, pode, mas não é permanente nem estratégico.','2026-10-24T18:52:20.887Z');
INSERT INTO "hyron_group_messages" ("id","group_id","sender_id","content","created_at") VALUES('7401d902-62be-4b8e-b1a3-eb72685a12f6','16de0e2b-d78f-4d72-887f-2abe9735c305','060cf3ef-0b23-43f4-83dd-b0740499bb5a','@Bicuço, seu novo codinome oficial é Falcão Carmesim, atribuído por mim, Teo, durante a Operação Hospício Digital.','2026-10-24T19:53:19.578Z');
